      "kind": "objective",
      "text": "understand reasons for the shapes of, and bond angles in, simple molecules and ions with up to six outer pairs of electrons (any combination of bonding pairs and lone pairs) Examples should include BeCl2, BCl3, CH4, NH3, NH4+, H2O, CO2, PCl5(g) and SF6(g) and related molecules and ions; as well as simple organic molecules in this specification.",
