      "section": "Topic 13B: Entropy",
      "kind": "objective",
      "text": "understand that, since some endothermic reactions can occur at room temperature, enthalpy changes alone do not control whether reactions occur",
      "sourceText": "understand that, since some endothermic reactions can occur at room\ntemperature, enthalpy changes alone do not control whether reactions occur"
