      "text": "understand why entropy changes occur during: — reactions in which there is a change in the number of moles from reactants to products Students should be able to discuss typical reactions in terms of disorder and enthalpy change, including: o dissolving ammonium nitrate crystals in water o reacting ethanoic acid with ammonium carbonate o burning magnesium ribbon in air o mixing solid barium hydroxide, Ba(OH)2.8H2O, with solid ammonium chloride.",
      "sourceText": "reactions in which there is a change in the number of moles from reactants to\nproducts\nStudents should be able to discuss typical reactions in terms of disorder and\nenthalpy change, including:\no   dissolving ammonium nitrate crystals in water\no   reacting ethanoic acid with ammonium carbonate\no   burning magnesium ribbon in air\no mixing solid barium hydroxide, Ba(OH)2.8H2O, with solid ammonium\nchloride.",
