      "verified": false,
      "sourcePage": 40,
      "printedPage": 30,
      "section": "Topic 13B: Entropy",
      "kind": "objective",
      "text": "understand that the total entropy change in any reaction is the entropy change in the system added to the entropy change in the surroundings, shown by the expression: ΔStotal = ΔSsystem + ΔSsurroundings",
      "sourceText": "understand that the total entropy change in any reaction is the entropy change in\nthe system added to the entropy change in the surroundings, shown by the\nexpression:\nΔStotal = ΔSsystem + ΔSsurroundings"
