      "verified": false,
      "sourcePage": 40,
      "printedPage": 30,
      "section": "Topic 13B: Entropy",
      "kind": "objective",
      "text": "be able to calculate the entropy change for the system, ΔSsystem , in a reaction, given the entropies of the reactants and products",
      "sourceText": "be able to calculate the entropy change for the system, ΔSsystem , in a reaction,\ngiven the entropies of the reactants and products"
