      "section": "Topic 13B: Entropy",
      "kind": "objective",
      "text": "be able to calculate the entropy change in the surroundings, and hence ΔStotal , using the expression: ∆H ∆Ssurroundings = − T",
      "sourceText": "be able to calculate the entropy change in the surroundings, and hence ΔStotal ,\nusing the expression:\n∆H\n∆Ssurroundings =\n−\nT",
