      "topic": 0,
      "reference": "B.1.3",
      "text": "Identify uncertainties in measurements and use simple techniques to determine uncertainty when data are combined",
      "examples": "Candidates may be tested on their ability to: ●    determine uncertainty when two burette readings are used to calculate a titre value",
      "category": "maths",
      "source": "official",
      "verified": false,
      "sourcePage": 97,
